<?php
require __DIR__.'/src/commerce.php';
$u=require_customer();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_input(INPUT_POST,'item_id',FILTER_VALIDATE_INT);$note=trim((string)($_POST['note']??''));if(!$id||mb_strlen($note)>2000){$error='الطلب غير صحيح.';}else{$q=db()->prepare("SELECT id,price FROM items WHERE id=? AND type IN ('product','service') AND published=1");$q->execute([$id]);$item=$q->fetch();if(!$item)$error='العنصر غير متاح.';else{$ref='NSQ-'.strtoupper(bin2hex(random_bytes(6)));$q=db()->prepare('INSERT INTO customer_orders(customer_id,item_id,reference,amount,note) VALUES(?,?,?,?,?)');$q->execute([$u['id'],$id,$ref,$item['price'],$note]);$oid=(int)db()->lastInsertId();log_action('customer',(int)$u['id'],'order_created','order',$oid);redirect('orders.php?created=1');}}}
$q=db()->prepare('SELECT o.*,i.title FROM customer_orders o JOIN items i ON i.id=o.item_id WHERE o.customer_id=? ORDER BY o.id DESC');$q->execute([$u['id']]);$orders=$q->fetchAll();$labels=['new'=>'جديد','reviewing'=>'قيد المراجعة','approved'=>'مقبول','completed'=>'مكتمل','cancelled'=>'ملغي'];
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css?v=4"><title>طلباتي | نَسَق</title></head><body><header class="site-header"><nav class="wrap site-nav"><a class="brand" href="index.php"><span class="brand-mark">ن</span>نَسَق</a><a class="btn secondary" href="account.php">حسابي</a></nav></header><main class="wrap"><section class="pagehead"><h1>طلباتي</h1><p>طلبات الخدمات والمنتجات ومراحل تنفيذها.</p></section><?php if(isset($_GET['created'])):?><div class="notice">تم إنشاء طلبك بنجاح. الطلب لا يعني إتمام الدفع.</div><?php endif;?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><div class="tablewrap"><table><thead><tr><th>المرجع</th><th>العنصر</th><th>القيمة</th><th>الحالة</th><th>التاريخ</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['reference'])?></td><td><?=e($o['title'])?></td><td><?=$o['amount']!==null?e(number_format((float)$o['amount'],2)).' ر.س':'حسب الاتفاق'?></td><td><span class="status"><?=e($labels[$o['status']]??$o['status'])?></span></td><td><?=e($o['created_at'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$orders):?><p class="empty">لا توجد طلبات حتى الآن. <a href="index.php?page=shop">تصفح المنتجات</a></p><?php endif;?></div></main></body></html>